"""Build private browser self-check and three-step buyer guide."""
import json,html
from pathlib import Path
from directory_brand import brand_page
ROOT=Path(__file__).parent
STYLE='''body{font:16px/1.6 system-ui;color:#252525;background:#faf9f6;margin:0}main{max-width:950px;margin:auto;padding:24px}a{color:#a90000}h1{line-height:1.15;font-size:clamp(28px,4vw,38px)}section,article{background:white;border:1px solid #ccc;padding:16px;margin:12px 0}label{display:block;margin:10px 0}input,select,button,textarea{font:inherit;padding:8px;max-width:100%;box-sizing:border-box}textarea{width:100%;min-height:70px}button{cursor:pointer}input:not([type=file]),select{width:100%}.muted{color:#555;font-size:.85rem}.actions,.step-tabs,.step-actions{display:flex;flex-wrap:wrap;gap:8px}progress{width:100%;height:14px}.math-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.print-evidence{display:none;white-space:pre-wrap;overflow-wrap:anywhere}.domain-bar{height:8px;background:#a90000;border-radius:8px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #3367b1;outline-offset:2px}@media(max-width:650px){main{padding:16px}.math-grid{grid-template-columns:1fr}section,article{padding:12px}h1{margin:16px 0}}@media print{body{background:white}main{padding:0}.actions,.step-tabs,.step-actions,.flow-progress{display:none!important}.tool-step,.assessment-step,.tool-step[hidden],.assessment-step[hidden]{display:block!important}section,article{break-inside:auto}.print-evidence{display:block}#assessment-form label{display:none}}'''
def shell(title,body,js):
 return brand_page('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+STYLE+'__VHG_CSS__</style></head><body><main>__VHG_BRAND__<h1>'+title+'</h1>'+body+'</main><script>'+js+'</script></body></html>')
def main():
 data=json.loads((ROOT/'data/business-assessment.json').read_text());qs=data['questions'];domains=list(dict.fromkeys(q['domain'] for q in qs));steps=[]
 for index,domain in enumerate(domains):
  cards=[]
  for q in [q for q in qs if q['domain']==domain]:
   id=q['id'];card=f'<article id="question-{id}"><small class="muted">{id}</small><h3>{html.escape(q["question"])}</h3>'
   if q.get('verified_on'):card+='<p class="muted">Citation checked '+q['verified_on']+'</p>'
   card+='<details><summary>What counts as evidence?</summary><p>'+html.escape(q['evidence'])+' · Weight '+str(q['weight'])+'</p><label>Evidence / notes<textarea data-note="'+id+'"></textarea></label><label>Owner<input data-owner="'+id+'"></label><label>Target date<input type="date" data-due="'+id+'"></label><label>Next action<textarea data-action="'+id+'"></textarea></label></details>'
   card+='<label>Score<select data-id="'+id+'" data-weight="'+str(q['weight'])+'"><option value="">Not assessed</option>'+''.join('<option value="'+str(n)+'">'+str(n)+' - '+label+'</option>' for n,label in enumerate(['Absent / unknown','Informal / partial','Documented','Implemented and evidenced']))+'</select></label><p class="print-evidence" data-question="'+id+'"></p></article>'
   cards.append(card)
  steps.append('<section class="assessment-step" data-step="'+str(index)+'"'+(' hidden' if index else '')+'><h2>'+html.escape(domain)+'</h2>'+''.join(cards)+'</section>')
 body='''<p>A 33-question self-check for Ohio cannabis businesses preparing for banking, financing or an internal review. Score what you can show today, not what you intend. This measures documented readiness. It does not certify compliance or guarantee bank acceptance. Ohio rule citations checked October 11, 2026.</p><div class="flow-progress"><p id="flow-status" role="status"></p><progress id="flow-progress" max="33" value="0" aria-label="Questions answered"></progress><button id="show-results" type="button">View results / save draft</button></div><form id="assessment-form">'''+''.join(steps)+'''</form><section id="assessment-results" class="assessment-step" data-step="8" hidden><h2>Your results</h2><p id="score" aria-live="polite"></p><ul id="domains"></ul><label>Review purpose<select id="purpose"><option value="internal">Internal review</option><option value="banking">Banking</option><option value="financing">Financing</option><option value="startup">Startup planning</option></select></label><p id="purpose-help">Review gaps with process owners and set a retest date.</p><h2>Prioritized action plan</h2><div id="action-plan"></div><details><summary>Evidence to gather</summary><ul id="evidence-list"></ul></details><div class="actions"><button id="save" data-track="assessment-save">Save draft</button><button id="export" data-track="assessment-export">Export answers</button><label>Import<input id="import" type="file" accept=".json,application/json"></label><button id="print" data-track="assessment-print">Print</button><button id="clear-draft">Clear draft</button></div><p id="save-status" role="status">Answers stay in this browser. Export a backup; clear drafts on shared devices.</p><a href="directory.html">Find business support</a></section><div class="step-actions"><button id="assessment-back" type="button">Back</button><button id="assessment-next" type="button">Next</button></div>'''
 js='const qs='+json.dumps(qs).replace('<','\\u003c')+';'+(ROOT/'assets/assessment-ui.js').read_text()+'\n'+(ROOT/'assets/assessment-flow.js').read_text()
 (ROOT/'assessment.html').write_text(shell('Business self-check',body,js))
 body='''<div class="step-tabs" role="group" aria-label="Shopping steps"><button data-buyer-step="0" aria-pressed="true">1. Plan</button><button data-buyer-step="1" aria-pressed="false">2. Do the math</button><button data-buyer-step="2" aria-pressed="false">3. Before you go</button></div><section class="tool-step" data-tool-step="0"><h2>Your plan</h2><label>What are you trying to accomplish?<input placeholder="My goal and questions"></label><label>Experience<select><option>First time</option><option>Occasional</option><option>Returning after a break</option><option>Experienced, new product form</option></select></label><label>Product<select id="product"><option>Gummies / edibles</option><option>Flower / pre-rolls</option><option>Concentrates / cartridges</option><option>Tincture / oral oil</option><option>Topicals</option><option>Not sure</option></select></label><label>Budget including tax and fees $<input type="number" min="0"></label><div class="actions"><a href="assets/dispensary-visit-companion.pdf" data-track="download-visit-companion">Download my plan (PDF)</a><button id="print" data-track="buyer-guide-print">Print</button></div></section><div class="tool-step" data-tool-step="1" hidden><div class="math-grid"><section><h2>THC &amp; CBD label math</h2><label>Label basis<select id="label-basis"><option value="piece">mg per piece</option><option value="ml">mg per mL</option><option value="package">mg per whole package</option><option value="percent">Percent by weight</option></select></label><label>THC on label<input id="label-thc" type="number" min="0" step="any"></label><label>CBD on label (optional)<input id="label-cbd" type="number" min="0" step="any"></label><label id="label-amount-text" for="label-amount">Amount in pieces</label><input id="label-amount" type="number" min="0" step="any"><p id="label-result" role="status"></p><p class="muted">Shows what the label says is in the amount you enter. It doesn't predict effects.</p></section><section><h2>How long will it last?</h2><label>Quantity in one package<input id="quantity" type="number" min="0" step="any"></label><label>Unit<select id="unit"><option>pieces</option><option>mL</option><option>grams</option></select></label><label>Planned amount per use<input id="amount" type="number" min="0" step="any"></label><label>Planned uses per week<input id="frequency" type="number" min="0" step="any"></label><label>Weeks to cover<input id="weeks" type="number" min="0" step="any"></label><p id="estimate" role="status">Enter estimates to calculate supply duration.</p><p id="possession-notice" role="status"></p><p class="muted">A shopping estimate, not a dosing recommendation.</p></section></div></div><section class="tool-step" data-tool-step="2" hidden><h2>Before you go</h2><details><summary>Ask before buying</summary><ul><li>THC and CBD per serving and package?</li><li>How to measure it; when do effects begin and wear off?</li><li>Final price, required device, allergens and batch testing?</li><li>Secure storage and expiration?</li></ul></details><p>For new or occasional edible users, <a href="https://www.canada.ca/en/health-canada/services/drugs-medication/cannabis/resources/lower-your-risks.html">Health Canada</a> gives a starting reference of 2.5 mg THC or less and advises allowing up to four hours for full effects before taking more. Discuss medicines and health concerns with a clinician or pharmacist.</p><p>Do not drive impaired. Lock products away from children and pets. Avoid combining with alcohol.</p>'''+(ROOT/'templates/ohio-basics.html').read_text()+'''<a href="assets/dispensary-visit-companion.pdf" data-track="download-visit-companion">Visit plan + experience journal (PDF)</a> · <a href="assets/dispensary-shopping-guide.pdf">Full education guide (PDF)</a></section>'''
 js=(ROOT/'assets/buyer-math.js').read_text()+'\n'+(ROOT/'assets/buyer-flow.js').read_text()
 (ROOT/'buyer-guide.html').write_text(shell('Shop smart',body,js))
if __name__=='__main__':main()
